#define VPN1_SHIFT 21
#define VPN0_SHIFT 12

typedef uint64_t PTE;

static inline uintptr_t kva2pa(uintptr_t kva)
{
    return (uintptr_t)(kva - (uintptr_t)g_phys + PHYS_BASE);
}
static inline uintptr_t pa2kva(uintptr_t pa)
{
    return (uintptr_t)((uintptr_t)g_phys + (pa - PHYS_BASE));
}

static inline void clear_pgdir(PTE* pgdir_addr) { memset(pgdir_addr, 0, 4096); }

static inline long get_pfn(PTE entry) { return ((entry >> _PAGE_PFN_SHIFT) & PFN_MASK); }
static inline void set_pfn(PTE *entry, uint64_t pfn)
{
    *entry = *entry & ATTRIBUTE_MASK;
    *entry = *entry | (pfn << _PAGE_PFN_SHIFT);
}
static inline uintptr_t get_pa(PTE entry)
{
    return (((entry >> _PAGE_PFN_SHIFT) & PFN_MASK) << NORMAL_PAGE_SHIFT);
}
static inline long get_attribute(PTE entry, uint64_t mask) { return ((entry & mask) != 0); }
static inline void set_attribute(PTE *entry, uint64_t bits) { *entry = *entry | bits; }
static inline void clear_attribute(PTE *entry, uint64_t bits) { *entry = *entry & ~bits; }

static inline uintptr_t get_kva_of(uintptr_t va, uintptr_t pgdir)
{
    uintptr_t pgdir_kva = pa2kva((uintptr_t)pgdir);
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
    PTE* s = (PTE*)get_pa((uintptr_t)*((PTE*)pgdir_kva + VPN2));
    s = (PTE*)pa2kva((uintptr_t)s);
    PTE* l = (PTE*)get_pa((uintptr_t)*((PTE*)s + VPN1));
    l = (PTE*)pa2kva((uintptr_t)l);
    uintptr_t pa = get_pa((uintptr_t)*((PTE*)l + VPN0)) | (va & PAGE_OFFSET_MASK);
    return pa2kva(pa);
}
