static int translate(uintptr_t va, uintptr_t pgdir, void **out, PTE *leafout)
{
    uint64_t vpn[3] = { (va>>VPN0_SHIFT)&VPN_MASK, (va>>VPN1_SHIFT)&VPN_MASK, (va>>VPN2_SHIFT)&VPN_MASK };
    PTE *t = (PTE*)pa2kva(pgdir);
