    PTE leaf = t[vpn[0]];
    if (leafout) *leafout = leaf;
    if (!get_attribute(leaf, _PAGE_PRESENT)) return -1;
    *out = (void*)(pa2kva(get_pa(leaf)) + (va & PAGE_OFFSET_MASK));
